import{_ as a,o as t,c as n,ag as r}from"./chunks/framework.ePeAWSvT.js";const p=JSON.parse('{"title":"v5.15 — July 2026","description":"","frontmatter":{},"headers":[],"relativePath":"guide/release-v5-15.md","filePath":"guide/release-v5-15.md"}'),i={name:"guide/release-v5-15.md"};function o(s,e,l,c,d,g){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="v5-15-—-july-2026" tabindex="-1">v5.15 — July 2026 <a class="header-anchor" href="#v5-15-—-july-2026" aria-label="Permalink to &quot;v5.15 — July 2026&quot;">​</a></h1><p>Changes since v5.14 (December 2025). This release spans the platform, connectors, agents, and the admin experience. Below is a customer-facing summary; internal refactors and infrastructure work are omitted.</p><nav class="table-of-contents"><ul><li><a href="#new-connectors-integrations">New Connectors &amp; Integrations</a></li><li><a href="#branding-white-labeling">Branding &amp; White-Labeling</a></li><li><a href="#ai-assistant-data-access">AI &amp; Assistant Data Access</a></li><li><a href="#configuration-builder-experience">Configuration Builder Experience</a></li><li><a href="#data-sync-mapping-engine">Data Sync &amp; Mapping Engine</a></li><li><a href="#webhooks-external-access">Webhooks &amp; External Access</a></li><li><a href="#reliability-performance">Reliability &amp; Performance</a></li><li><a href="#users-access-management">Users &amp; Access Management</a></li><li><a href="#documentation">Documentation</a></li></ul></nav><h2 id="new-connectors-integrations" tabindex="-1">New Connectors &amp; Integrations <a class="header-anchor" href="#new-connectors-integrations" aria-label="Permalink to &quot;New Connectors &amp; Integrations&quot;">​</a></h2><p>We expanded the connector catalog across HR, communications, logistics, procurement, accounting, CPQ and more — and made existing connectors more capable and easier to authenticate.</p><p><strong>New connectors:</strong> Slack (messaging &amp; alert delivery), Paycor (HRIS), Paycom (HRIS), Gaiia (billing), Talkdesk (contact center), Track Unit (telematics), Wherefour (ERP/traceability), Fireflies.ai (meeting intelligence), Salesmate (CRM), Tai (TMS), Cincom CPQ, SAP Ariba (cXML procurement), Sage Intacct (accounting/ERP), Loopio (RFP/proposals), FedaDB (database), and PCI Pal (secure payments).</p><ul><li><strong>Multi-auth connectors</strong> — Connectors can now offer more than one authentication method, so you pick the one that fits your environment.</li><li><strong>Simpler, more reliable authentication</strong> — API-orchestrated OAuth with PKCE, automatic detection of expired refresh tokens with a one-click re-authenticate action, and connection verification built into every connector&#39;s Test action.</li><li><strong>Deeper existing-connector coverage</strong> — Extended Eptura Asset, NetSuite 2026.1 support, Egnyte moved to long-lived refresh-token OAuth, Rental Result SOAP handling, and corrected Mortgage Automator &amp; WInTeam definitions.</li><li><strong>File System as a connector</strong> — Local and network file locations are now a first-class connector you can configure like any other system.</li></ul><h2 id="branding-white-labeling" tabindex="-1">Branding &amp; White-Labeling <a class="header-anchor" href="#branding-white-labeling" aria-label="Permalink to &quot;Branding &amp; White-Labeling&quot;">​</a></h2><p>A complete white-labeling system lets partners and enterprises present the platform under their own brand — no code required.</p><ul><li><strong>Full brand kit</strong> — Upload your logo, assistant avatar, page title and web manifest; set your primary color and theme; override favicon, Apple touch icon and Windows tile.</li><li><strong>Light &amp; dark variants</strong> — Provide distinct brand assets for light and dark mode.</li><li><strong>Effortless editing</strong> — Drag an image onto the preview to upload it, watch changes render live, and see updates propagate instantly to other open tabs.</li><li><strong>Branding at provisioning</strong> — New customer environments can be stood up with default branding already applied.</li></ul><h2 id="ai-assistant-data-access" tabindex="-1">AI &amp; Assistant Data Access <a class="header-anchor" href="#ai-assistant-data-access" aria-label="Permalink to &quot;AI &amp; Assistant Data Access&quot;">​</a></h2><p>Your synced data is now directly usable by AI assistants (via MCP) — for retrieval, analysis and data entry — with the guardrails and performance to use it at scale.</p><ul><li><strong>Rich queries</strong> — Filter records, compare one property against another, and use <code>StartsWith</code>/<code>EndsWith</code> operators.</li><li><strong>Follow the relationships</strong> — Expand related records inline (joins), filter on those related properties, and shape the response to only the fields you need.</li><li><strong>Aggregations</strong> — Sum, Average, Count, Min, Max and Distinct-Count with group-by, including across joined relationships.</li><li><strong>Fast lookups</strong> — Bulk get by ID list, scalable keyword search with paging, and smart routing of ID lookups.</li><li><strong>Conversational data entry</strong> — Guided forms let the assistant create <em>and</em> update records, with fields scoped by transaction type.</li><li><strong>Saved queries</strong> — List and run saved queries directly from the assistant.</li><li><strong>Governance</strong> — Per-tool permissions, query logging and result counts keep AI access controlled and auditable.</li></ul><h2 id="configuration-builder-experience" tabindex="-1">Configuration Builder Experience <a class="header-anchor" href="#configuration-builder-experience" aria-label="Permalink to &quot;Configuration Builder Experience&quot;">​</a></h2><p>The admin experience for building and testing integrations got a major usability pass — faster feedback, fewer surprises, and clearer editing throughout.</p><ul><li><strong>Map Preview</strong> — Test map groups in real time from the mapping editor and see exactly what output a configuration produces before you deploy.</li><li><strong>Drag &amp; drop mapping</strong> — Reorder and restructure maps by dragging, with a unified Properties tab that brings related settings together.</li><li><strong>Inline config validation</strong> — Configuration errors are surfaced right in the forms as you build.</li><li><strong>Better Test Connector</strong> — Test read actions from the data-source tab, run SQL tests with copy-able result cells, clearer loading and failure feedback, and reliable error toasts.</li><li><strong>Safer edits</strong> — Type-to-confirm before deleting high-impact configurations, plus a &quot;Compare with Live&quot; action.</li><li><strong>Everyday conveniences</strong> — Timezone typeahead, CSV template generator, &quot;Copy Webhook URL&quot;, extra primary keys in Maintain Index, and editors for connector- and builder-level AI instructions.</li></ul><h2 id="data-sync-mapping-engine" tabindex="-1">Data Sync &amp; Mapping Engine <a class="header-anchor" href="#data-sync-mapping-engine" aria-label="Permalink to &quot;Data Sync &amp; Mapping Engine&quot;">​</a></h2><p>The core engine gained substantial new mapping power — more transforms, smarter parent/child handling, and finer control over how records are matched, filtered and written.</p><ul><li><strong>New transforms</strong> — Convert to UTC, US state name ↔ abbreviation, and IANA timezone normalization.</li><li><strong>Parent/child mapping</strong> — Map from a parent entity (including multi-hop ancestors), skip parent saves while processing children, and skip inner saves when children fail.</li><li><strong>Looping lists</strong> — Conditional read/write filters, delete-aware maps that remove embedded child items, and in-place grouping.</li><li><strong>Record matching</strong> — Chained existence lookups, key-extraction actions on save, subscriber-side primary-key selection, and extra-key lookups.</li><li><strong>Parallel publishing</strong> — Publish work concurrently for higher throughput.</li><li><strong>Session values</strong> — Capture and reuse values across a run, including across multiple lists.</li><li><strong>Flexible paging</strong> — Cursor-based and &quot;has-more&quot; paging strategies for large data sets.</li><li><strong>Queue publishers</strong> — Queue-message and queue-release publishers, with release-if-trigger-arrives-first handling.</li><li><strong>More control</strong> — Variables in data selectors, insert-at-root for XML, and trimming preload responses to just the fields you need.</li></ul><h2 id="webhooks-external-access" tabindex="-1">Webhooks &amp; External Access <a class="header-anchor" href="#webhooks-external-access" aria-label="Permalink to &quot;Webhooks &amp; External Access&quot;">​</a></h2><p>Real-time inbound events and outbound lookup endpoints make it easier to connect the platform to the tools around it.</p><ul><li><strong>Inbound webhooks</strong> — A dedicated webhook endpoint accepts events from external systems, with a one-click &quot;Copy Webhook URL&quot; and per-connector signature verification.</li><li><strong>Cross-reference lookups</strong> — A dedicated cross-reference endpoint, plus a Power Automate custom connector, lets other tools resolve entity IDs across systems.</li><li><strong>Event fan-out</strong> — A single inbound document can drive multiple downstream records via response-selector fan-out.</li><li><strong>API Gateway</strong> — Create and manage API gateways directly from the admin experience.</li><li><strong>Clearer API errors</strong> — Platform API responses now return human-readable, actionable error messages.</li></ul><h2 id="reliability-performance" tabindex="-1">Reliability &amp; Performance <a class="header-anchor" href="#reliability-performance" aria-label="Permalink to &quot;Reliability &amp; Performance&quot;">​</a></h2><p>A large share of this release went into making sync more dependable and operations more hands-off.</p><ul><li><strong>Self-updating agents</strong> — Remote, secure agent updates with identity certificates from a managed vault, a guided Windows installer, and automatic upgrade of older agents.</li><li><strong>Messaging hardening</strong> — Long-running saves no longer lose their message lock, redeliveries settle correctly, and obsolete subscriptions are cleaned up automatically.</li><li><strong>Resilient outbound calls</strong> — Idempotency-aware transient retry on outbound API requests recovers from momentary network and vendor hiccups without creating duplicates.</li><li><strong>No more stuck runs</strong> — Data pulls that hang now time out cleanly instead of taking down processing, and dependent-publisher runs report status correctly.</li><li><strong>Better error visibility</strong> — Failures to record message metadata are now surfaced instead of silently lost.</li><li><strong>Search &amp; bulk processing</strong> — Optimized search-entity sync and bulk processing for large data volumes.</li></ul><h2 id="users-access-management" tabindex="-1">Users &amp; Access Management <a class="header-anchor" href="#users-access-management" aria-label="Permalink to &quot;Users &amp; Access Management&quot;">​</a></h2><ul><li><strong>User provisioning API</strong> — Create users programmatically as part of your onboarding workflows.</li><li><strong>Manage users at scale</strong> — A user grid with mass-edit functions and role deletes that cascade cleanly to affected users.</li><li><strong>Tool-level permissions</strong> — Fine-grained permissions govern which AI tools each user can access.</li></ul><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><ul><li><strong>Web-based User Guide</strong> — This guide: a fast, searchable site with cross-linked topics and navigation.</li><li><strong>Mobile friendly</strong> — Improved table and layout treatment for reading on any device.</li><li><strong>Authentication reference</strong> — Supported authentication methods are now fully documented.</li></ul>',29)])])}const h=a(i,[["render",o]]);export{p as __pageData,h as default};
